<?php require_once __DIR__.'/config/auth.php'; if(current_user()) redirect('dashboard.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $u=trim($_POST['username']??''); $s=db()->prepare('SELECT * FROM users WHERE username=?');$s->execute([$u]);$user=$s->fetch(); if($user && $user['status']==='active' && password_verify($_POST['password']??'',$user['password_hash'])){login_user($user);redirect('dashboard.php');}else{log_activity('failed login','user',null,$u,'Invalid credentials');}$error=isset($_GET['timeout'])?'You were signed out after 10 minutes of inactivity.':'Invalid username or password, or the account is inactive.';}elseif(isset($_GET['timeout']))$error='You were signed out after 10 minutes of inactivity.'; ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="theme-color" content="#132c60"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><meta name="apple-mobile-web-app-title" content="Botaan"><link rel="manifest" href="manifest.webmanifest"><link rel="apple-touch-icon" href="assets/icons/apple-touch-icon.png"><link rel="icon" type="image/png" href="assets/icons/favicon-32.png"><title>Login · <?=e(APP_NAME)?></title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="assets/css/v3.css"></head><body class="login-body"><main class="login-page"><section class="login-box login-card"><div class="login-logo-image"><img src="assets/img/logo-square.png" alt="Botaan logo"></div><p class="eyebrow">BOTAAN</p><h1>Welcome back</h1><p class="muted login-subtitle">Sign in to manage your archive securely.</p><?php if($error):?><div class="alert error" role="alert"><?=e($error)?></div><?php endif;?><form method="post" class="login-form"><div class="field"><label for="username">Username</label><input id="username" name="username" autocomplete="username" required autofocus placeholder="Enter your username"></div><div class="field"><label for="password">Password</label><div class="input-wrap"><input id="password" type="password" name="password" autocomplete="current-password" required placeholder="Enter your password"><button type="button" class="password-toggle" aria-label="Show password" data-toggle-password="password">Show</button></div></div><button class="btn login-submit" type="submit">Sign in securely <span>→</span></button></form><p class="login-footer">Botaan Notary Archive &amp; Payment System</p></section></main><script>document.querySelector('[data-toggle-password]')?.addEventListener('click',e=>{const b=e.currentTarget,i=document.getElementById(b.dataset.togglePassword),show=i.type==='password';i.type=show?'text':'password';b.textContent=show?'Hide':'Show'});</script></body></html>
